import{d as g,C as i,o as h,c as u,a3 as a,E as e,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"论语·尧曰","description":"《论语》第 20 篇「尧曰」——三章原文与导读。允执其中、四海困穷天禄永终、尊五美屏四恶，以及全书末章「不知命，无以为君子也」。","frontmatter":{"title":"论语·尧曰","description":"《论语》第 20 篇「尧曰」——三章原文与导读。允执其中、四海困穷天禄永终、尊五美屏四恶，以及全书末章「不知命，无以为君子也」。","category":"guide","aliases":["尧曰","尧曰篇","尧曰第二十","论语尧曰","lunyu 尧曰"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-20.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-20.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-20.md"},x=g({...p,setup(m){const o=[{id:"yi",label:"一、允执其中",showLabel:!0,sentences:[["尧曰：“咨！尔舜，天之",{text:"历数",glossary:"lishu"},"在尔躬，",{text:"允执其中",glossary:"yunzhihaiqizhong"},"。四海困穷，天禄永终。”舜亦以命禹。曰：“予小子",{text:"履",glossary:"lv-shang"},"，敢用",{text:"玄牡",glossary:"xuanmu"},"，敢昭告于皇皇后帝：有罪不敢赦，帝臣不",{text:"蔽",glossary:"bi-bai"},"，",{text:"简在帝心",glossary:"jianzaidixin"},"。朕躬有罪，无以万方；万方有罪，罪在朕躬。”周有大",{text:"赉",glossary:"lai"},"，善人是富。“虽有周亲，不如仁人。百姓有过，在予一人。”谨权量，审法度，修废官，四方之政行焉。兴灭国，继绝世，举逸民，天下之民归心焉。所重：民、食、丧、祭。宽则得众，信则民任焉，敏则有功，公则说。"]],note:"尧曰：「咨！尔舜，天之历数在尔躬，允执其中。四海困穷，天禄永终」——唉！舜啊，上天之大命在尔身，当诚实地执守中道；若四海之民困穷，天禄便永终。舜亦以此命禹，曰：「予小子履，敢用玄牡，敢昭告于皇皇后帝：有罪不敢赦，帝臣不蔽，简在帝心。朕躬有罪，无以万方；万方有罪，罪在朕躬」——舜又以此告诫禹，说：我后生小子履，敢用黑色公牛，明告于伟大的天帝：有罪者不敢赦，天帝之臣不敢蔽，皆由天帝心中鉴察；朕身有罪，不连累万方；万方有罪，罪在朕身。（其后又记周之大赉、虽有周亲不如仁人、谨权量审法度、兴灭国继绝世等诰命之辞，合为一章。）"},{id:"er",label:"二、尊五美，屏四恶",showLabel:!0,sentences:[["子张问于孔子曰：“何如斯可以从政矣？”子曰：“尊五美，屏四恶，斯可以从政矣。”子张曰：“何谓五美？”子曰：“君子惠而不费，劳而不怨，欲而不贪，泰而不骄，威而不猛。”子张曰：“何谓惠而不费？”子曰：“因民之所利而利之，斯不亦惠而不费乎？择可劳而劳之，又谁怨？欲仁而得仁，又焉贪？君子无众寡，无小大，无敢慢，斯不亦泰而不骄乎？君子正其衣冠，尊其瞻视，俨然人望而畏之，斯不亦威而不猛乎？”子张曰：“何谓四恶？”子曰：“不教而杀谓之虐；不戒视成谓之暴；慢令致期谓之贼；犹之与人也，出纳之",{text:"吝",glossary:"lin-yao"},"，谓之",{text:"有司",glossary:"yousi"},"。”"]],note:"子张问于孔子曰：「何如斯可以从政矣」？子曰：「尊五美，屏四恶，斯可以从政矣」——尊五美、屏四恶，斯可从政。曰「何谓五美」？曰：「君子惠而不费，劳而不怨，欲而不贪，泰而不骄，威而不猛」。曰「何谓惠而不费」？曰：「因民之所利而利之，斯不亦惠而不费乎？择可劳而劳之，又谁怨？欲仁而得仁，又焉贪？君子无众寡，无小大，无敢慢，斯不亦泰而不骄乎？君子正其衣冠，尊其瞻视，俨然人望而畏之，斯不亦威而不猛乎」——就民所利而利之，即惠而不费；择可劳而劳之，又何怨？欲仁得仁，又何贪？无众寡小大皆不慢，即泰而不骄；正衣冠、尊瞻视、俨然可畏，即威而不猛。曰「何谓四恶」？曰：「不教而杀谓之虐，不戒视成谓之暴，慢令致期谓之贼，犹之与人也，出纳之吝谓之有司」——不教而杀谓之虐，不戒而责成谓之暴，慢令而致期谓之贼，当予而吝于出纳谓之有司（小家子气）。"},{id:"san",label:"三、不知命，无以为君子也",showLabel:!0,sentences:[["孔子曰：“不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也。”"]],note:"孔子曰：「不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也」——不知命则无以为君子，不知礼则无以立身，不知言则无以知人。三句收束全书。"}],r=[{id:"lishu",term:"历数",pinyin:"lì shù",meaning:"天道运行的次序，此指天命所归的运数。"},{id:"yunzhihaiqizhong",term:"允执其中",pinyin:"yǔn zhí qí zhōng",meaning:"诚实地持守中正之道。这句是儒家「执中」之说的源头，后来成为「十六字心传」的核心。"},{id:"lv-shang",term:"履",pinyin:"lǚ",meaning:"商汤的名。此下为汤告天之辞。"},{id:"xuanmu",term:"玄牡",pinyin:"xuán mǔ",meaning:"黑色的公牛（祭祀用牲）。"},{id:"bi-bai",term:"蔽",pinyin:"bì",meaning:"遮蔽、隐瞒。帝臣不蔽：对天帝的臣属（贤人）不敢隐瞒不举。"},{id:"jianzaidixin",term:"简在帝心",pinyin:"jiǎn zài dì xīn",meaning:"简：阅、明察（一说「简」为「存」）。天帝心里明白——即一切都在天帝鉴察之中。"},{id:"lai",term:"赉",pinyin:"lài",meaning:"赏赐。周有大赉：周朝得到上天的丰厚赏赐（指得天下）。"},{id:"lin-yao",term:"吝",pinyin:"lìn",meaning:"吝啬、舍不得。出纳之吝：该给的时候舍不得给。"},{id:"yousi",term:"有司",pinyin:"yǒu sī",meaning:"专管具体事务的官吏。此处指「像管库房的小吏那样小家子气」，是贬义比喻。"}];return(y,n)=>{const s=i("DaoTextReading"),l=i("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=a('<h1 id="论语·尧曰" tabindex="-1">论语·尧曰 <a class="header-anchor" href="#论语·尧曰" aria-label="Permalink to &quot;论语·尧曰&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《尧曰》只有三章，却是<strong>全书的一个收束</strong>。</p><p>第一章是《论语》里最古老的一段文字——尧传位给舜时的训辞（「<strong>允执其中</strong>」），舜又以此命禹；接着是商汤告天之辞（「朕躬有罪，无以万方；万方有罪，罪在朕躬」）与周武王的话（「虽有周亲，不如仁人」）；最后是治国的大纲：谨权量、审法度、修废官，兴灭国、继绝世、举逸民，所重民食丧祭。</p><p>第二章是孔子答子张问政：<strong>尊五美、屏四恶</strong>。五美（惠而不费、劳而不怨、欲而不贪、泰而不骄、威而不猛）各有一句解释；四恶（虐、暴、贼、有司）则是对暴政的四种定性。</p><p>第三章是全书最后一章，只有三句：<strong>「不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也。」</strong>——从命、礼、言三处，把一生的学问收了口。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',7)),e(s,{colophon:"尧曰第二十 · 三章",tone:"ink",sections:o,glossary:r,"default-mode":"slips","aria-label":"论语·尧曰 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(l,{items:[{term:"历数",pinyin:["lì","shù"],meaning:"天道运行的次序，此指天命所归的运数。"},{term:"允执其中",pinyin:["yǔn","zhí","qí","zhōng"],meaning:"诚实地持守中正之道。这句是儒家「执中」之说的源头，后来成为「十六字心传」的核心。"},{term:"履",pinyin:["lǚ"],meaning:"商汤的名。此下为汤告天之辞。"},{term:"玄牡",pinyin:["xuán","mǔ"],meaning:"黑色的公牛（祭祀用牲）。"},{term:"蔽",pinyin:["bì"],meaning:"遮蔽、隐瞒。帝臣不蔽：对天帝的臣属（贤人）不敢隐瞒不举。"},{term:"简在帝心",pinyin:["jiǎn","zài","dì","xīn"],meaning:"简：阅、明察（一说「简」为「存」）。天帝心里明白——即一切都在天帝鉴察之中。"},{term:"赉",pinyin:["lài"],meaning:"赏赐。周有大赉：周朝得到上天的丰厚赏赐（指得天下）。"},{term:"吝",pinyin:["lìn"],meaning:"吝啬、舍不得。出纳之吝：该给的时候舍不得给。"},{term:"有司",pinyin:["yǒu","sī"],meaning:"专管具体事务的官吏。此处指「像管库房的小吏那样小家子气」，是贬义比喻。"}]}),n[2]||(n[2]=a('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《尧曰》三章，是<strong>全书的一个总收束</strong>。</p><p>第一章往前追得很远——从尧传舜、舜传禹的训辞（<strong>「允执其中」</strong>）开始，经汤、周武王的告天之言，最后归纳为治国的几条大纲（谨权量、审法度、修废官；兴灭国、继绝世、举逸民；所重民食丧祭）。<strong>这一章几乎把儒家政治理想的源头与纲领都放进去了。</strong></p><p>第二章是孔子答子张问政，提出<strong>尊五美、屏四恶</strong>。五美讲的是上位者的自我要求（惠而不费、劳而不怨、欲而不贪、泰而不骄、威而不猛），四恶讲的是暴政的四种形态（虐、暴、贼、有司）——<strong>一正一反，把「怎样才配治人」说清了。</strong></p><p>第三章用三句话收尾：不知命，无以为君子；不知礼，无以立；不知言，无以知人。<strong>命（内）、礼（外）、言（人），恰好覆盖了人一生的三个面向。</strong> 以这样三句结束整部《论语》，极为克制，也极为完整。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「允执其中」是儒家政治哲学最早的一句话</strong>：它讲的是<strong>在位者要持守中正，而衡量的底线是百姓的处境</strong>——「四海困穷，天禄永终」，百姓困穷，天命就没了。这是后世「民本」思想的最早表述。</li><li><strong>「万方有罪，罪在朕躬」是全篇最重的一句</strong>：天下有罪，责任在我一人——<strong>这是对「执政者承担什么」最彻底的答案</strong>，两千年后仍少见这样的表述。</li><li><strong>「尊五美、屏四恶」是一份完整的执政者标准</strong>：五美要行为得当，四恶要逐条禁绝；尤其**「不教而杀谓之虐」「慢令致期谓之贼」**——<strong>先让百姓知道，再要求他们做到</strong>，这是对权力的基本约束。</li><li><strong>「虽有周亲，不如仁人」是对「用人唯亲」的正面否定</strong>：《论语》以此作结，颇有深意。</li><li><strong>末章三句分别是三种「不知道的后果」</strong>：不知命（不能成为君子）、不知礼（立不住）、不知言（看不清人）。<strong>把全书的学问收在三个「要知道」上。</strong></li><li><strong>「不知言，无以知人也」把「听人说话」提到了极高的位置</strong>：《述而》说「不知言」，这一篇说不会分辨言辞就没法了解人——<strong>这既是修养，也是能力。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>把「四海困穷，天禄永终」当作权力的底线</strong>：无论带团队还是做管理，<strong>评判标准最终要回到最下面的人的处境。</strong></li><li><strong>用「万方有罪，罪在朕躬」检查自己的担当</strong>：出了问题，第一反应是找责任人，还是先承担？<strong>尤其当你在上面的时候。</strong></li><li><strong>用「五美」当领导力的自评表</strong>：施惠而不浪费、让人做事而不引起怨恨、有追求而不贪、安详而不傲慢、有威而不凶。</li><li><strong>用「四恶」检查管理制度</strong>：「不教而杀」（没培训就考核）、「不戒视成」（没提醒就要求结果）、「慢令致期」（安排仓促却限时很紧）、「出纳之吝」（该给的舍不得给）——<strong>这四条今天仍是最常见的管理病。</strong></li><li><strong>用末章三句当一生的三个提醒</strong>：知命（知道什么不由我决定）、知礼（知道该怎么做人）、知言（知道如何听懂别人）。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《论语》的最后三章。</p><p>第一章往回追得很远，一直追到尧传位给舜的时候。尧说：你这位舜啊，上天的大命落在你身上了，你要诚实地守住中正。<strong>如果天下百姓困苦穷穷，上天给你的禄位就永远终止了。</strong></p><p>——中国政治思想最古老的一句话，说的是：百姓过得不好，你的位置就保不住。</p><p>舜又把这话传给禹。然后是商汤告天：我有罪，不要牵连天下人；天下人有罪，罪过都归我一人。周武王也说：虽然有至亲，也不如有仁人。</p><p>第二章是孔子答子张问政。他要子张做到五件事、禁掉四件事。五件是：施惠而不浪费、让人做事而不招怨、有欲望而不贪、安详而不傲慢、有威严而不凶猛。四件是：不加教化就杀，叫虐；不先告诫就要结果，叫暴；命令下得晚却限期很急，叫贼；该给人时舍不得给，叫小吏作风。</p><p>第三章只有三句，是全书最后的话：</p><p><strong>不知命，无以为君子也；不知礼，无以立也；不知言，无以知人也。</strong></p><p>——知道什么不由自己决定，知道该怎么立身，知道怎么听懂别人。一部《论语》，到这里收了口。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「允执其中」「四海困穷，天禄永终」——如果用它来评价我所在的组织或我在意的事，达标了吗？</li><li>「万方有罪，罪在朕躬」——我在领导、管理、甚至家庭角色里，愿不愿意说这句话？</li><li>「尊五美」——五条里我做得最好的是哪一条？最差的是哪一条？</li><li>「屏四恶」——「不教而杀」「不戒视成」「慢令致期」「出纳之吝」，我自己有没有做过其中任何一条？</li><li>「不知命，无以为君子也」——我接受「有些事不由我决定」吗？我分得清哪些是命、哪些是自己的问题吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-19">论语·子张</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',26))])}}});export{b as __pageData,x as default};
